<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {RefreshCw,Search,ChevronLeft,ChevronRight,ArrowRight,Copy,Check,X} from '@lucide/vue';
import {refreshFeedback as vRefreshFeedback} from '../../../shared/directives/refreshFeedback';
import {assetApi} from '../api';
import SeedCleanupPanel from './SeedCleanupPanel.vue';
import {useI18n,assetConfirm} from '../uiPorts';
import type {ProjectSeed,ProjectSeedId,ProjectSeedPage,ProjectSeedDetail,ProjectSeedRoundPage} from '../seeds/types';
const props=defineProps<{projectId?:number;refreshVersion?:number;discoverLabel?:string}>();
const emit=defineEmits<{discover:[]}>();
const {tr}=useI18n();
const cleanupOpen=ref(false);
const historyPage=ref(1),olderBatches=ref<NonNullable<ProjectSeedPage['exclusionBatches']>>([]),historyMore=ref(true),historyReading=ref(false);
const checkedIds=ref<Set<number>>(new Set()),exceptIds=ref<Set<number>>(new Set()),allMatches=ref(false),exclusionScope=ref('exact'),mutationBusy=ref(false),mutationError=ref(''),mutationNotice=ref('');
let selectionRevision=0,historySequence=0;
const selectable=computed(()=>data.value?.items.filter(s=>s.trustStatus!=='excluded')||[]);
const matchingSelectableCount=computed(()=>data.value?.selectableTotal??(search.value.trim()===''&&kind.value==='all'&&trust.value==='all'&&data.value?.summary?Math.max(0,(data.value.total||0)-data.value.summary.excluded):data.value?.total||0));
const selectedCount=computed(()=>allMatches.value?Math.max(0,matchingSelectableCount.value-exceptIds.value.size):checkedIds.value.size);
const isSeedChecked=(id:number)=>allMatches.value?!exceptIds.value.has(id):checkedIds.value.has(id);
const allPageChecked=computed(()=>selectable.value.length>0&&selectable.value.every(s=>isSeedChecked(s.id)));
const pagePartlyChecked=computed(()=>!allPageChecked.value&&selectable.value.some(s=>isSeedChecked(s.id)));
function toggleSeed(id:number){if(mutationBusy.value||reading.value)return;selectionRevision++;const next=new Set(allMatches.value?exceptIds.value:checkedIds.value);next.has(id)?next.delete(id):next.add(id);if(allMatches.value)exceptIds.value=next;else checkedIds.value=next;}
function togglePage(){if(mutationBusy.value||reading.value)return;selectionRevision++;const wasChecked=allPageChecked.value,next=new Set(allMatches.value?exceptIds.value:checkedIds.value);for(const row of selectable.value){if(allMatches.value?!wasChecked:wasChecked)next.delete(row.id);else next.add(row.id);}if(allMatches.value)exceptIds.value=next;else checkedIds.value=next;}
function selectAllMatches(){if(mutationBusy.value||reading.value)return;selectionRevision++;allMatches.value=true;checkedIds.value=new Set();exceptIds.value=new Set();}
function resetChecked(){selectionRevision++;checkedIds.value=new Set();exceptIds.value=new Set();allMatches.value=false;}
watch(exclusionScope,()=>{selectionRevision++;});
function selectionQuery(){return {projectId:props.projectId,search:search.value.trim(),kind:kind.value,trust:trust.value,page:1,pageSize:50};}
async function excludeSeeds(ids?:number[]){
 const projectId=props.projectId,g=generation,revision=selectionRevision;if(!projectId||mutationBusy.value||reading.value||error.value)return;
 mutationBusy.value=true;mutationError.value='';mutationNotice.value='';
 const filterSnapshot=JSON.stringify(selectionQuery());
 const selection={...(ids?{seedIds:ids}:allMatches.value?{query:selectionQuery(),exceptSeedIds:[...exceptIds.value]}:{seedIds:[...checkedIds.value]}),scope:exclusionScope.value};
 const current=()=>!disposed&&g===generation&&revision===selectionRevision&&JSON.stringify(selectionQuery())===filterSnapshot;
 try{
  const preview=await assetApi.manageProjectSeedExclusion({projectId,action:'preview',...selection});
  if(!current())return;
  if(!preview.count){resetChecked();mutationNotice.value=tr('没有可排除的种子，可能已被排除。','No seeds to exclude; they may already be excluded.');return;}
  const familyText=selection.scope==='siblings'&&(preview.familyCount||0)>0?tr(`范围：${(preview.families||[]).join('、')}${(preview.familyCount||0)>(preview.families?.length||0)?` 等 ${preview.familyCount} 个域名范围`:''}。仅连带本项目当前已存在的域名/CNAME 种子；不连带证书指纹或未来新增种子。`,`Ranges: ${(preview.families||[]).join(', ')}. Includes existing domain/CNAME seeds in this project only, not certificate fingerprints or future seeds.`):selection.scope==='siblings'?tr('没有可联动的域名范围；证书指纹等条目仅按所选值处理。','No expandable domain range; fingerprints and other entries are handled only as explicitly selected.'):tr('仅排除具体值，不连带兄弟子域。','Exact selected values only.');
  if(!await assetConfirm(tr(`排除 ${preview.count} 个种子（所选 ${preview.selectedCount??preview.count} 个，联动增加 ${preview.addedCount||0} 个）？${familyText} 资产与历史保留，可整批撤销。`,`Exclude ${preview.count} seeds (${preview.selectedCount??preview.count} selected; ${preview.addedCount||0} additional)? ${familyText} Assets and history remain; the batch can be undone.`))||!current())return;
  const result=await assetApi.manageProjectSeedExclusion({projectId,action:'apply',...selection,expectedDigest:preview.digest,operationId:crypto.randomUUID()});
  if(disposed||g!==generation)return;
  resetChecked();mutationNotice.value=tr(`已排除 ${result.count} 个种子，可在下方撤销。`,`Excluded ${result.count} seeds. Undo is available below.`);await refresh();
 }catch(e){if(!disposed&&g===generation)mutationError.value=String(e)+tr('；未自动重发，请刷新确认结果。','; not replayed automatically. Refresh to check the result.');}
 finally{if(!disposed&&g===generation)mutationBusy.value=false;}
}
async function loadOlderBatches(){
 const projectId=props.projectId,g=generation,targetPage=historyPage.value+1;if(!projectId||historyReading.value)return;const seq=++historySequence;historyReading.value=true;
 try{const result=await assetApi.manageProjectSeedExclusion({projectId,action:'history',batchPage:targetPage});if(disposed||g!==generation||seq!==historySequence)return;const known=new Set([...(data.value?.exclusionBatches||[]),...olderBatches.value].map(b=>b.id));olderBatches.value.push(...(result.items||[]).filter(b=>!known.has(b.id)));historyPage.value=targetPage;historyMore.value=(result.total||0)>historyPage.value*10;}
 catch(e){if(!disposed&&g===generation&&seq===historySequence)mutationError.value=String(e);}
 finally{if(!disposed&&g===generation&&seq===historySequence)historyReading.value=false;}
}
async function restoreBatch(batchId:string){
 const projectId=props.projectId,g=generation;if(!projectId||mutationBusy.value)return;mutationBusy.value=true;mutationError.value='';
 try{const result=await assetApi.manageProjectSeedExclusion({projectId,action:'restore',batchId,operationId:crypto.randomUUID()});if(disposed||g!==generation)return;mutationNotice.value=tr(`已撤销本批 ${result.restored} 条排除规则。`,`Restored ${result.restored} seeds.`);await refresh();}
 catch(e){if(!disposed&&g===generation)mutationError.value=String(e)+tr('；未自动重发，请刷新确认结果。','; not replayed automatically. Refresh to check the result.');}
 finally{if(!disposed&&g===generation)mutationBusy.value=false;}
}

const bulkElement=ref<HTMLElement>(),bulkLeft=ref(24),bulkRight=ref(24),bulkHeight=ref(44);
const workspaceElement=ref<HTMLElement>(),detailElement=ref<HTMLElement>(),detailScrollElement=ref<HTMLElement>();
const stickyTop=ref(140),detailDockTop=ref(140),detailDockRight=ref(24),detailViewportHeight=ref<number>(),copiedSeedId=ref<ProjectSeedId>(),copyError=ref('');
let chromeObserver:ResizeObserver|undefined;
// The business shell scrolls the document, with two sticky chrome rows. The
// section navigation may wrap, so a fixed offset would hide the detail header.
function updateLayout(){
 const workspaceBounds=workspaceElement.value?.getBoundingClientRect?.();
 if(workspaceBounds){bulkLeft.value=Math.max(12,workspaceBounds.left);bulkRight.value=Math.max(12,window.innerWidth-workspaceBounds.right);}
 bulkHeight.value=bulkElement.value?.getBoundingClientRect?.().height||44;
 const bottomClearance=selectedCount.value?bulkHeight.value+36:40;
 const main=workspaceElement.value?.closest?.('.main-area');
 if(!main)return;
 const topbar=main.querySelector<HTMLElement>(':scope > .topbar');
 const sections=main.querySelector<HTMLElement>(':scope > .workspace-section-navigation');
 stickyTop.value=Math.ceil((topbar?.getBoundingClientRect().height||0)+(sections?.getBoundingClientRect().height||0)+12);
 const bounds=detailElement.value?.parentElement?.getBoundingClientRect?.();
 const detailTop=bounds?.top??detailElement.value?.getBoundingClientRect?.().top;
 if(detailTop!==undefined){
  detailDockTop.value=Math.max(stickyTop.value,detailTop);
  detailViewportHeight.value=Math.max(120,Math.floor(window.innerHeight-detailDockTop.value-bottomClearance));
 }
 if(bounds)detailDockRight.value=Math.max(12,window.innerWidth-bounds.right);
}
onMounted(()=>{
 updateLayout();window.addEventListener('resize',updateLayout,{passive:true});window.addEventListener('scroll',updateLayout,{passive:true});
 const main=workspaceElement.value?.closest?.('.main-area');
 if(main&&typeof window.ResizeObserver==='function'){
  chromeObserver=new window.ResizeObserver(updateLayout);
  if(bulkElement.value)chromeObserver.observe(bulkElement.value);
  for(const element of main.querySelectorAll(':scope > .topbar,:scope > .workspace-section-navigation'))chromeObserver.observe(element);
 }
});
watch([selectedCount,allMatches],()=>{void nextTick(updateLayout);},{flush:'post'});
const data=ref<ProjectSeedPage>(),detail=ref<ProjectSeedDetail>(),selectedId=ref<ProjectSeedId>();
const roundData=ref<ProjectSeedRoundPage>(),roundReading=ref(false),roundError=ref('');
const search=ref(''),kind=ref('all'),trust=ref('all'),page=ref(1),pageSize=ref(50),detailPage=ref(1);
const reading=ref(false),detailReading=ref(false),initializing=ref(false),error=ref(''),detailError=ref(''),prepareError=ref('');
let generation=0,sequence=0,detailSequence=0,roundSequence=0,disposed=false,prepared=false,searchTimer:ReturnType<typeof setTimeout>|undefined,pollTimer:ReturnType<typeof setTimeout>|undefined;
const pages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/pageSize.value)));
const historyPages=computed(()=>Math.max(1,Math.ceil((detail.value?.observationsTotal||0)/(detail.value?.pageSize||20))));
const summary=computed(()=>data.value?.summary);
const rounds=computed(()=>roundData.value?.items||[]);
const roundPages=computed(()=>Math.max(1,Math.ceil((roundData.value?.total||0)/10)));
const selected=computed(()=>detail.value?.seed||data.value?.items.find(row=>row.id===selectedId.value));
const kinds:Record<string,[string,string]>={domain:['域名','Domain'],fingerprint:['证书 SHA-256','Certificate SHA-256'],cname:['CNAME','CNAME']};
const trusts:Record<string,[string,string]>={accepted:['已认可 / 确认范围','Accepted / confirmed scope'],ready:['精确查询就绪','Exact query ready'],verified:['证据已核验','Evidence verified'],needs_evidence:['缺少核验证据','Evidence missing'],conflict:['证据冲突','Conflicting evidence'],excluded:['已排除','Excluded']};
const sources:Record<string,[string,string]>={hunter_query:['Hunter 查询','Hunter query'],hunter_page:['Hunter 分页','Hunter page'],hunter_result:['Hunter 关联结果','Hunter related result'],public_ct:['公开 CT 记录','Public CT record'],free_tls:['TLS 补采','TLS enrichment'],free_ct:['CT 发现','CT discovery'],free_dns:['DNS 发现','DNS discovery'],free_dns_a:['DNS IPv4 地址','DNS IPv4 records'],free_dns_aaaa:['DNS IPv6 地址','DNS IPv6 records'],free_dns_cname:['DNS 别名','DNS aliases'],free_tls_previous_leaf:['历史 TLS 叶证书','Previous TLS leaf certificate'],free_cname:['CNAME 发现','CNAME discovery'],fofa:['FOFA','FOFA'],hunter:['Hunter','Hunter'],tls:['TLS 证书','TLS certificate'],ct:['证书透明度','Certificate transparency'],dns:['DNS / CNAME','DNS / CNAME'],history:['历史记录','Historical record'],historical_baseline:['历史基线','Historical baseline'],certificate_sha256:['证书指纹','Certificate fingerprint'],certificate_name:['证书名称','Certificate name'],certificate_cn:['证书 CN','Certificate CN'],certificate_domain:['测绘证书关联','Provider certificate relation'],certificate_transparency:['证书透明度','Certificate transparency'],public_ct_subject:['公开 CT 叶证书','Public CT leaf certificate'],dns_cname:['DNS CNAME','DNS CNAME'],cname:['CNAME','CNAME'],observed_host:['已收录主机','Observed host'],confirmed_scope:['已确认范围','Confirmed scope'],page:['已采集页面','Collected page'],page_or_inline_script:['页面 / 内联脚本','Page / inline script']};
const kindLabel=(value:string)=>kinds[value]?tr(...kinds[value]):value;
const seedValue=(seed:ProjectSeed)=>seed.wildcard&&!seed.value.startsWith('*.')?`*.${seed.value}`:seed.value;
const compactSeedValue=(seed:ProjectSeed)=>seed.kind==='fingerprint'&&seed.value.length===64?`${seed.value.slice(0,12)}…${seed.value.slice(-12)}`:seedValue(seed);
async function copySeed(){
 const item=selected.value,projectId=props.projectId,g=generation;if(!item)return;
 const seedId=item.id;copyError.value='';
 try{
  if(!navigator.clipboard?.writeText)throw Error(tr('无法访问剪贴板，请选中完整值复制。','Clipboard unavailable; select and copy the complete value.'));
  await navigator.clipboard.writeText(seedValue(item));
  if(!disposed&&g===generation&&props.projectId===projectId&&selectedId.value===seedId)copiedSeedId.value=seedId;
 }catch(e){if(!disposed&&g===generation&&props.projectId===projectId&&selectedId.value===seedId)copyError.value=String(e);}
}
const assetIds=(entry:{assetId?:number|null;assetIds?:number[]})=>entry.assetIds?.length?entry.assetIds:entry.assetId!=null?[entry.assetId]:[];
const trustLabel=(value:string)=>trusts[value]?tr(...trusts[value]):tr('状态未识别','Unknown status');
const sourceLabel=(value:string)=>sources[value]?tr(...sources[value]):value;
const roundState=(value:string)=>({active:tr('执行中','Active'),superseded:tr('已切换目标，历史保留','Target changed; history retained'),running:tr('执行中','Running'),paused:tr('已暂停','Paused'),completed:tr('已完成','Completed'),interrupted:tr('已中断','Interrupted'),failed:tr('失败','Failed'),blocked:tr('待恢复','Blocked'),steady:tr('本轮完成','Round complete'),collecting:tr('采集中','Collecting')} as Record<string,string>)[value]||value;
const roundLabel=(value:number|null|undefined)=>typeof value==='number'&&Number.isFinite(value)?tr(`第 ${value} 轮`,`Round ${value}`):tr('历史基线 · 轮次未知','Historical baseline · round unknown');
const numberLabel=(value:number|null|undefined)=>typeof value==='number'&&Number.isFinite(value)?value.toLocaleString():tr('未记录','Not recorded');
function timeLabel(value:string|null|undefined){if(!value)return tr('时间未记录','Time not recorded');const date=new Date(/Z$|[+-]\d\d:\d\d$/.test(value)?value:value.replace(' ','T')+'Z');return Number.isNaN(date.getTime())?value:date.toLocaleString(tr('zh-CN','en-US'),{hour12:false});}
function evidenceText(value:unknown){return typeof value==='string'?value:JSON.stringify(value,null,2);}
function clearSelection(){selectedId.value=undefined;detail.value=undefined;detailError.value='';copiedSeedId.value=undefined;copyError.value='';detailReading.value=false;detailPage.value=1;detailSequence++;}
function poll(projectId:number,g:number){clearTimeout(pollTimer);pollTimer=setTimeout(()=>{if(!disposed&&g===generation&&props.projectId===projectId&&!prepareError.value)void loadList();},1500);}
async function prepare(projectId:number,g:number){
 if(prepared||disposed||g!==generation)return;prepared=true;initializing.value=true;
 try{await assetApi.prepareProjectSeeds(projectId);if(!disposed&&g===generation)poll(projectId,g);}
 catch(e){if(!disposed&&g===generation){prepareError.value=String(e);clearTimeout(pollTimer);}}
 finally{if(!disposed&&g===generation)initializing.value=false;}
}
async function loadList():Promise<boolean|undefined>{
 const projectId=props.projectId,g=generation,seq=++sequence;if(!projectId||disposed)return;reading.value=true;
 try{const value=await assetApi.listProjectSeeds({projectId,search:search.value.trim(),kind:kind.value,trust:trust.value,page:page.value,pageSize:pageSize.value});
  if(disposed||g!==generation||seq!==sequence)return;if(value.projectId!==projectId||!Array.isArray(value.items))throw Error('project_seed_scope_mismatch');if(value.ready&&typeof value.total==='number'&&page.value>Math.max(1,Math.ceil(value.total/pageSize.value))){page.value=Math.max(1,Math.ceil(value.total/pageSize.value));return await loadList();}data.value=value;error.value='';
  if(!roundData.value||roundData.value.page===1)roundData.value={projectId,items:value.rounds||[],total:value.roundsTotal??value.rounds?.length??0,page:1,pageSize:10,historyBeforeTracking:'unknown'};
  if(value.ready===false){if(!prepared)void prepare(projectId,g);if(!prepareError.value)poll(projectId,g);}else clearTimeout(pollTimer);
  return true;
 }catch(e){if(g===generation&&seq===sequence&&!disposed){error.value=String(e);return false;}}finally{if(g===generation&&seq===sequence&&!disposed)reading.value=false;}
}
async function loadDetail(){
 const projectId=props.projectId,seedId=selectedId.value,g=generation,seq=++detailSequence;if(!projectId||seedId===undefined||disposed)return;detailReading.value=true;
 try{const value=await assetApi.readProjectSeed(projectId,seedId,detailPage.value,20);if(disposed||g!==generation||seq!==detailSequence)return;
  if(value.projectId!==projectId||value.seed.id!==seedId||!Array.isArray(value.observations))throw Error('project_seed_detail_scope_mismatch');detail.value=value;detailError.value='';return true;
 }catch(e){if(g===generation&&seq===detailSequence&&!disposed){detailError.value=String(e);return false;}}finally{if(g===generation&&seq===detailSequence&&!disposed)detailReading.value=false;}
}
async function selectSeed(row:ProjectSeed){
 if(selectedId.value===row.id&&detail.value)return;
 clearSelection();selectedId.value=row.id;const requestedId=row.id,requestedGeneration=generation;
 await nextTick();
 if(disposed||requestedGeneration!==generation||selectedId.value!==requestedId)return;
 updateLayout();detailScrollElement.value?.scrollTo?.({top:0});detailElement.value?.focus?.({preventScroll:true});
 await loadDetail();
}
async function closeDetail(){
 const seedId=selectedId.value,g=generation;clearSelection();await nextTick();
 if(disposed||g!==generation||selectedId.value!==undefined)return;
 const buttons=workspaceElement.value?.querySelectorAll?.<HTMLButtonElement>('[data-seed-id]');
 Array.from(buttons||[]).find(button=>button.dataset.seedId===String(seedId))?.focus({preventScroll:true});
}
async function loadRoundPage(value:number){
 const projectId=props.projectId,g=generation,seq=++roundSequence;if(!projectId||disposed)return;roundReading.value=true;
 try{const result=await assetApi.listProjectSeedRounds(projectId,Math.max(1,Math.min(roundPages.value,value)),10);if(disposed||g!==generation||seq!==roundSequence)return;
  if(result.projectId!==undefined&&result.projectId!==projectId||!Array.isArray(result.items))throw Error('project_seed_round_scope_mismatch');roundData.value=result;roundError.value='';
 }catch(e){if(!disposed&&g===generation&&seq===roundSequence)roundError.value=String(e);}finally{if(!disposed&&g===generation&&seq===roundSequence)roundReading.value=false;}
}
async function refresh(){historySequence++;historyReading.value=false;olderBatches.value=[];historyPage.value=1;historyMore.value=true;await Promise.all([loadList(),...(selectedId.value!==undefined?[loadDetail()]:[]),...(roundData.value&&roundData.value.page>1?[loadRoundPage(roundData.value.page)]:[])]);}
function clearFilterSelection(){if(selectedCount.value||allMatches.value)mutationNotice.value=tr('筛选条件已改变，已清空原筛选下的选择。翻页与修改每页条数会保留选择。','Filters changed; the old selection was cleared. Paging and page size preserve selection.');resetChecked();}
function resetFilter(){clearFilterSelection();clearTimeout(searchTimer);page.value=1;clearSelection();void loadList();}
function searchSeeds(){clearFilterSelection();clearTimeout(searchTimer);searchTimer=setTimeout(resetFilter,250);}
async function changePage(value:number){if(reading.value||mutationBusy.value)return;const previous=page.value,g=generation;page.value=Math.max(1,Math.min(pages.value,value));clearSelection();const request=loadList(),seq=sequence;if(await request===false&&g===generation&&seq===sequence&&!disposed)page.value=previous;}
async function changeHistoryPage(value:number){if(detailReading.value)return;const previous=detailPage.value,g=generation;detailPage.value=Math.max(1,Math.min(historyPages.value,value));const request=loadDetail(),seq=detailSequence;if(await request===false&&g===generation&&seq===detailSequence&&!disposed)detailPage.value=previous;}
watch([kind,trust],resetFilter);
watch(pageSize,()=>{clearTimeout(searchTimer);page.value=1;clearSelection();void loadList();});
watch(()=>props.projectId,()=>{cleanupOpen.value=false;olderBatches.value=[];historyPage.value=1;historyMore.value=true;historyReading.value=false;historySequence++;resetChecked();exclusionScope.value='exact';mutationBusy.value=false;mutationError.value='';mutationNotice.value='';generation++;sequence++;detailSequence++;roundSequence++;roundData.value=undefined;roundReading.value=false;roundError.value='';clearTimeout(searchTimer);clearTimeout(pollTimer);prepared=false;initializing.value=false;prepareError.value='';page.value=1;data.value=undefined;error.value='';reading.value=false;clearSelection();if(props.projectId)void loadList();},{immediate:true,flush:'sync'});
watch(()=>props.refreshVersion,()=>void refresh());
onUnmounted(()=>{chromeObserver?.disconnect();window.removeEventListener('resize',updateLayout);window.removeEventListener('scroll',updateLayout);disposed=true;generation++;sequence++;detailSequence++;roundSequence++;clearTimeout(searchTimer);clearTimeout(pollTimer);});
</script>
<template>
<section ref="workspaceElement" class="project-seeds" :class="{'has-selection':selectedCount>0}" :style="{'--seed-sticky-top':`${stickyTop}px`,'--seed-bulk-left':`${bulkLeft}px`,'--seed-bulk-right':`${bulkRight}px`,'--seed-bulk-height':`${bulkHeight}px`,'--seed-bottom-clearance':`${selectedCount?bulkHeight+36:40}px`,'--seed-detail-bottom':`${selectedCount?bulkHeight+36:16}px`,'--seed-detail-dock-top':`${detailDockTop}px`,'--seed-detail-dock-right':`${detailDockRight}px`,'--seed-detail-viewport-height':detailViewportHeight===undefined?undefined:`${detailViewportHeight}px`}" data-testid="project-seeds-workspace">
 <header class="seed-heading"><div><span class="eyebrow">PROJECT SEEDS</span><h2>{{tr('项目种子','Project seeds')}}</h2><p>{{tr('按项目保留每次发现、证据与查询历史；核验状态不代表资产当前存活或探测授权。','Retains discovery, evidence and query history for this project. Verification does not prove current liveness or grant probing permission.')}}</p></div><div class="seed-heading-actions"><button v-if="projectId" class="button ghost compact" data-seeds-action="cleanup" @click="cleanupOpen=!cleanupOpen">{{tr(cleanupOpen?'收起清洗进度':'AI 清洗种子',cleanupOpen?'Hide cleanup':'AI seed cleanup')}}</button><button v-refresh-feedback="{scope:projectId,busy:reading||detailReading||roundReading,error:error||detailError||prepareError||roundError}" class="button ghost compact" :disabled="!projectId||reading||detailReading||roundReading" data-seeds-action="refresh" @click="refresh"><RefreshCw :size="15"/>{{tr('刷新','Refresh')}}</button><button v-if="projectId" class="button primary compact" data-seeds-action="discover" @click="emit('discover')">{{discoverLabel||tr('继续增量发现','Continue incremental discovery')}}<ArrowRight :size="14"/></button></div></header>
 <p v-if="!projectId" class="seed-empty">{{tr('先选择一个工作空间，种子及历史仅在本项目内读取。','Choose a workspace. Seeds and their history are read only within that project.')}}</p>
 <template v-else>
  <SeedCleanupPanel v-if="cleanupOpen" :project-id="projectId" @changed="refresh"/>
  <p v-if="data?.ready===false" class="seed-initializing" role="status">{{prepareError?tr('历史种子整理尚未确认，可刷新状态或稍后重新进入。','Historical seed preparation is unconfirmed. Refresh status or return later.'):tr('正在整理历史种子，仅建立本地索引，不调用 AI、不联网、不消耗 Hunter 积分。','Preparing historical seeds locally. No AI, network or Hunter points are used.')}} <span v-if="prepareError" class="seed-error">{{prepareError}}</span></p>
  <details v-if="roundData&&roundData.total>0" class="seed-rounds"><summary>{{tr('发现轮次','Discovery rounds')}} · {{numberLabel(roundData.total)}} {{tr('轮','rounds')}}</summary><div><article v-for="round in rounds" :key="round.number"><b>{{roundLabel(round.number)}}</b><span>{{roundState(round.state)}}</span><small v-if="round.plannedQueries!=null">{{tr('精确查询','Exact queries')}} {{round.plannedQueries}}</small><time>{{timeLabel(round.startedAt)}} → {{round.completedAt?timeLabel(round.completedAt):tr('结束时间未记录','End time not recorded')}}</time></article></div><p>{{tr('暂停后恢复沿用同一轮；开始记录之前的历史轮次未知。','Resuming retains the same round. Historical rounds before tracking are unknown.')}}</p><p v-if="roundError" class="seed-error" role="alert">{{roundError}} · {{tr('保留上页历史','Previous history retained')}}</p><footer v-if="roundPages>1" class="seed-pagination"><span>{{roundData.page}} / {{roundPages}}</span><button class="button ghost compact" :disabled="roundReading||roundData.page<=1" data-seeds-action="previous-rounds" @click="loadRoundPage(roundData.page-1)"><ChevronLeft :size="14"/></button><button class="button ghost compact" :disabled="roundReading||roundData.page>=roundPages" data-seeds-action="next-rounds" @click="loadRoundPage(roundData.page+1)"><ChevronRight :size="14"/></button></footer></details>
  <div v-if="summary" class="seed-metrics"><span>{{tr('项目全部种子','All project seeds')}} <b>{{numberLabel(summary.total)}}</b></span><span>{{tr('证据已核验','Evidence verified')}} <b>{{numberLabel(summary.verified)}}</b></span><span>{{tr('已认可 / 确认范围','Accepted / confirmed scope')}} <b>{{numberLabel(summary.accepted||0)}}</b></span><span>{{tr('精确查询就绪','Exact query ready')}} <b>{{numberLabel(summary.ready||0)}}</b></span><span>{{tr('缺少核验证据','Evidence missing')}} <b>{{numberLabel(summary.needsEvidence)}}</b></span><span>{{tr('证据冲突','Evidence conflicts')}} <b>{{numberLabel(summary.conflicts)}}</b></span><span>{{tr('已排除','Excluded')}} <b>{{numberLabel(summary.excluded)}}</b></span><span>{{tr('历史基线','Historical baseline')}} <b>{{numberLabel(summary.historicalBaseline)}}</b></span></div>
  <p v-if="mutationError" class="seed-error" role="alert">{{mutationError}}</p><p v-if="mutationNotice" role="status">{{mutationNotice}}</p>
  <div class="seed-bulk-slot"><div ref="bulkElement" class="seed-bulk" :role="selectedCount?'region':undefined" :aria-label="tr('种子批量操作','Seed bulk actions')"><button class="button ghost compact" :disabled="initializing||mutationBusy" data-seeds-action="reconcile" @click="prepared=false;prepare(projectId!,generation)">{{initializing?tr('正在同步…','Syncing…'):tr('同步本地结论','Sync local decisions')}}</button><label><input type="checkbox" :checked="allPageChecked" :indeterminate="pagePartlyChecked" :disabled="reading||mutationBusy||!selectable.length" data-seeds-action="check-page" @change="togglePage"/> {{tr('全选本页','Select page')}}</label><button v-if="selectedCount>0&&!allMatches&&matchingSelectableCount>selectedCount" class="button ghost compact" data-seeds-action="check-all" :disabled="mutationBusy" @click="selectAllMatches">{{tr(`选择全部筛选结果（${matchingSelectableCount}）`,`Select all matches (${matchingSelectableCount})`)}}</button><select v-model="exclusionScope" :disabled="mutationBusy" :aria-label="tr('排除影响范围','Exclusion scope')" data-seeds-action="exclusion-scope"><option value="exact">{{tr('仅排除所选种子','Selected seeds only')}}</option><option value="siblings">{{tr('连带同域现有兄弟子域','Include existing sibling subdomains')}}</option></select><span>{{allMatches?tr(`已选 ${selectedCount} 个（筛选结果，已取消 ${exceptIds.size} 个）`,`Selected ${selectedCount} matches (${exceptIds.size} omitted)`):tr(`已选 ${selectedCount} 个（跨页保留）`,`Selected ${selectedCount} across pages`)}}</span><button class="button ghost compact" :disabled="reading||!!error||mutationBusy||!selectedCount" data-seeds-action="exclude-selected" @click="excludeSeeds()">{{mutationBusy?tr('正在处理…','Processing…'):tr('排除所选','Exclude selected')}}</button><button v-if="selectedCount" class="button ghost compact" :disabled="mutationBusy" data-seeds-action="clear-checked" @click="resetChecked">{{tr('清空选择','Clear selection')}}</button></div></div>
  <details v-if="data?.exclusionBatches?.length" class="seed-rounds"><summary>{{tr('排除记录与撤销','Exclusion history and undo')}}</summary><div><article v-for="batch in [...(data.exclusionBatches||[]),...olderBatches]" :key="batch.id"><span>{{batch.origin==='automatic'?tr('自动核验','Automatic verification'):tr('手动排除','Manual exclusion')}} · {{batch.count}} · {{timeLabel(batch.createdAt)}}</span><button v-if="!batch.restored" class="button ghost compact" :disabled="mutationBusy" :data-undo-batch="batch.id" @click="restoreBatch(batch.id)">{{tr('撤销本批排除','Undo batch')}}</button><span v-else>{{tr('已撤销','Undone')}}</span></article><button v-if="historyMore&&(data.exclusionBatches?.length||0)>=10" class="button ghost compact" :disabled="historyReading||mutationBusy" data-seeds-action="older-batches" @click="loadOlderBatches">{{historyReading?tr('正在读取…','Reading…'):tr('更早排除记录','Older exclusion batches')}}</button></div></details>
  <div class="seed-filters"><label class="seed-search"><Search :size="15"/><input v-model="search" maxlength="240" :placeholder="tr('搜索域名、证书指纹或 CNAME','Search domains, certificate fingerprints or CNAME')" :aria-label="tr('搜索项目种子','Search project seeds')" @input="searchSeeds"/></label><select v-model="kind" :aria-label="tr('种子类型','Seed type')"><option value="all">{{tr('全部种子类型','All seed types')}}</option><option v-for="(label,key) in kinds" :key="key" :value="key">{{tr(...label)}}</option></select><select v-model="trust" :aria-label="tr('可信状态','Verification status')"><option value="all">{{tr('全部可信状态','All verification states')}}</option><option v-for="(label,key) in trusts" :key="key" :value="key">{{tr(...label)}}</option></select></div>
  <p v-if="error" class="seed-error" role="alert">{{error}}<span v-if="data"> · {{tr('显示上次快照，当前读数尚未确认。','Showing the previous snapshot; current counts are unconfirmed.')}}</span></p>
  <div class="seed-content" :class="{selected:selectedId!==undefined}">
   <div class="seed-list-pane" :aria-busy="reading"><div class="seed-table-scroll" tabindex="0" :aria-label="tr('项目种子列表，可横向滚动','Project seed list, horizontally scrollable')"><table class="seed-table"><colgroup><col class="seed-col-value"/><col class="seed-col-subject"/><col class="seed-col-status"/><col class="seed-col-first"/><col class="seed-col-last"/><col class="seed-col-sources"/><col class="seed-col-count"/><col class="seed-col-actions"/></colgroup><thead><tr><th>{{tr('种子 / 类型','Seed / type')}}</th><th>{{tr('种子主体 / 证据字段','Subject / evidence field')}}</th><th>{{tr('核验状态','Verification')}}</th><th>{{tr('首次发现','First seen')}}</th><th>{{tr('最近出现','Last seen')}}</th><th>{{tr('来源','Sources')}}</th><th>{{tr('相关资产','Related assets')}}</th><th>{{tr('操作','Actions')}}</th></tr></thead><tbody><tr v-for="row in data?.items" :key="row.id" :class="{'is-selected':selectedId===row.id}"><td data-label="种子"><input type="checkbox" :checked="row.trustStatus!=='excluded'&&isSeedChecked(row.id)" :disabled="reading||mutationBusy||row.trustStatus==='excluded'" :data-seed-check="row.id" :aria-label="tr('选择种子','Select seed')+' '+seedValue(row)" @change="toggleSeed(row.id)"/><small class="seed-kind">{{kindLabel(row.kind)}}</small><button class="seed-value" :data-seed-id="row.id" :title="seedValue(row)" :aria-label="`${kindLabel(row.kind)}：${seedValue(row)}`" @click="selectSeed(row)">{{compactSeedValue(row)}}</button></td><td data-label="种子主体 / 证据字段" class="seed-subject"><template v-if="row.trustStatus!=='excluded'"><div v-for="subject in row.subjects" :key="subject.name+subject.field"><span>{{subject.name}}</span><small>{{subject.field}}</small></div><span v-if="!row.subjects?.length" class="seed-kind">{{tr('尚无主体字段','No subject field yet')}}</span></template><span v-else>—</span></td><td data-label="核验状态"><button class="seed-trust seed-status-button" :class="row.trustStatus" :title="row.trustReason" :aria-label="`${trustLabel(row.trustStatus)}：${row.trustReason}`" :data-seed-status="row.id" @click="selectSeed(row)">{{trustLabel(row.trustStatus)}}</button></td><td data-label="首次发现"><span>{{roundLabel(row.firstSeenRound)}}</span><small>{{timeLabel(row.firstSeenAt)}}</small></td><td data-label="最近出现"><span>{{timeLabel(row.lastSeenAt)}}</span><small v-if="row.historicalBaseline&&row.lastSeenRound==null">{{tr('台账记录时间','Ledger record time')}}</small><small v-if="row.lastSeenRound!==undefined&&row.lastSeenRound!==null">{{roundLabel(row.lastSeenRound)}}</small></td><td data-label="来源"><div class="seed-sources"><span v-for="source in row.sourceTypes" :key="source">{{sourceLabel(source)}}</span></div><small>{{numberLabel(row.observationCount)}} {{tr('条历史观察','historical observations')}}</small></td><td data-label="相关资产" class="seed-count">{{numberLabel(row.assetCount)}}</td><td class="seed-row-actions"><div class="seed-row-action-group"><button class="button ghost compact seed-detail-button" :data-seed-detail="row.id" :aria-expanded="selectedId===row.id" :aria-controls="`project-seed-detail-${projectId}`" @click="selectSeed(row)">{{tr('详情','Details')}}</button><button v-if="row.trustStatus!=='excluded'" class="button ghost compact" :disabled="reading||!!error||mutationBusy" :data-exclude-seed="row.id" @click="excludeSeeds([row.id])">{{tr('排除','Exclude')}}</button></div></td></tr></tbody></table><p v-if="!data?.items.length" class="seed-empty" role="status">{{reading?tr('正在读取项目种子…','Reading project seeds…'):error?tr('当前结果未知，不代表没有种子。','The current result is unknown, not empty.'):data?.ready===false?tr('本地历史索引尚未就绪，当前数量未知。','The local historical index is not ready; counts are unknown.'):tr('没有匹配的项目种子。已有历史记录会保留；发现流程会继续补充新观察。','No matching seeds. Historical records remain; discovery can append new observations.')}}</p></div>
    <footer class="seed-pagination"><span>{{tr('匹配','Matches')}} {{numberLabel(data?.total)}} · {{page}} / {{pages}}</span><select v-model.number="pageSize" :disabled="mutationBusy||reading" :aria-label="tr('每页条数','Rows per page')"><option :value="25">25 / {{tr('页','page')}}</option><option :value="50">50 / {{tr('页','page')}}</option></select><button class="button ghost compact" :disabled="reading||mutationBusy||page<=1" data-seeds-action="previous" @click="changePage(page-1)"><ChevronLeft :size="14"/></button><button class="button ghost compact" :disabled="reading||mutationBusy||page>=pages" data-seeds-action="next" @click="changePage(page+1)"><ChevronRight :size="14"/></button></footer>
