   <aside v-if="selectedId!==undefined" ref="detailElement" :id="`project-seed-detail-${projectId}`" class="seed-detail" tabindex="-1" :aria-busy="detailReading" :aria-label="tr('种子证据与历史','Seed evidence and history')" @keydown.esc.stop="closeDetail"><header><h3>{{tr('证据与查询历史','Evidence and query history')}}</h3><div class="seed-detail-actions"><button v-if="selected" class="button ghost compact" data-seeds-action="copy-seed" :aria-label="tr('复制完整种子值','Copy complete seed value')" @click="copySeed"><Check v-if="copiedSeedId===selectedId" :size="14"/><Copy v-else :size="14"/>{{copiedSeedId===selectedId?tr('已复制','Copied'):tr('复制','Copy')}}</button><button class="button ghost compact" :aria-label="tr('收起种子详情','Close seed details')" data-seeds-action="close-detail" @click="closeDetail"><X :size="15"/></button></div></header><div ref="detailScrollElement" class="seed-detail-scroll" tabindex="0" :aria-label="tr('种子详情，可独立滚动','Seed details, independently scrollable')"><p v-if="copyError" class="seed-error" role="alert">{{copyError}}</p><template v-if="selected"><small>{{kindLabel(selected.kind)}}</small><code class="detail-seed-value">{{seedValue(selected)}}</code><span class="seed-trust" :class="selected.trustStatus">{{trustLabel(selected.trustStatus)}}</span><p>{{selected.trustReason}}</p><div v-if="selected.trustStatus!=='excluded'&&selected.subjects?.length" class="seed-coverage"><strong>{{tr('种子主体与证据字段','Seed subject and evidence field')}}</strong><p v-for="subject in selected.subjects" :key="subject.name+subject.field"><b>{{subject.name}}</b><small>{{subject.field}} · {{subject.host}}</small></p></div><div class="seed-detail-facts"><span>{{tr('相关资产','Related assets')}} <b>{{numberLabel(selected.assetCount)}}</b></span><span v-if="selected.hunterEligible!==undefined">{{tr('Hunter 查询条件','Hunter eligibility')}} <b>{{selected.hunterEligible?tr('已满足','Eligible'):tr('未满足','Not eligible')}}</b></span></div><p v-if="selected.verificationCoverage" class="seed-coverage">{{tr('独立核验依据','Independent verification evidence')}} {{selected.verificationCoverage.verifiedEvidence}} {{tr('条','records')}} · {{tr('历史观察记录','Historical observations')}} {{selected.verificationCoverage.totalEvidence}} {{tr('条','records')}}<small>{{tr('历史观察包含查询页和状态记录，不作为核验证据分母。这些数量不是 AI 准确率或资产归属准确率。','Historical observations include query pages and status records; they are not a denominator for verified evidence. These counts are not AI accuracy or ownership accuracy.')}}</small></p><p v-if="selected.manualConclusion" class="seed-coverage">{{tr('已审样本','Reviewed samples')}} · {{selected.manualConclusion.reviewed}} / {{selected.manualConclusion.total}}<small>{{tr('认可','Accepted')}} {{selected.manualConclusion.accepted}} · {{tr('排除','Rejected')}} {{selected.manualConclusion.rejected}}<template v-if="selected.manualConclusion.reviewed>0&&selected.manualConclusion.acceptanceRate!=null"> · {{tr('人工已审样本认可率','Reviewed sample acceptance')}} {{(selected.manualConclusion.acceptanceRate*100).toFixed(1)}}%</template></small></p></template><p v-if="detailError" class="seed-error" role="alert">{{detailError}}<button class="button ghost compact" data-seeds-action="retry-detail" @click="loadDetail">{{tr('重试读取','Retry read')}}</button></p><p v-else-if="detailReading" class="seed-read-status" role="status">{{tr('正在读取历史，本页不会启动外部查询。','Reading history. This page does not start external queries.')}}</p>
    <div class="seed-history"><article v-for="entry in detail?.observations" :key="entry.id"><div class="history-title"><strong>{{sourceLabel(entry.sourceType)}}</strong><time>{{entry.historicalBaseline?tr('台账记录时间 · ','Ledger recorded · '):''}}{{timeLabel(entry.seenAt)}}</time></div><span class="history-round">{{roundLabel(entry.round)}}</span><p v-if="entry.sourceRef" class="history-reference">{{entry.sourceRef}}</p><div v-if="entry.queryKind||entry.queryId||entry.page!=null||entry.spentPoints!=null||entry.costUnknown" class="history-query"><span v-if="entry.queryKind">{{entry.queryKind}}</span><span v-if="entry.page!=null">{{tr('第','Page')}} {{entry.page}} {{tr('页','')}}</span><span v-if="entry.costUnknown" class="seed-error">{{tr('扣费待核对','Charge unresolved')}}</span><span v-else-if="entry.spentPoints!=null">{{entry.spentPoints}} {{tr('积分','points')}}</span><span v-else-if="entry.queryId||entry.page!=null">{{tr('积分未记录','Points not recorded')}}</span><small v-if="entry.queryId">{{entry.queryId}}</small></div><code v-if="entry.queryValue" class="history-query-value">{{entry.queryValue}}</code><small v-if="entry.assetCount!==undefined">{{tr('关联资产','Related assets')}} {{numberLabel(entry.assetCount)}}</small><details v-if="entry.evidence||assetIds(entry).length"><summary>{{tr('查看关联依据','View related evidence')}}</summary><p v-if="assetIds(entry).length">{{tr('资产编号','Asset IDs')}} · {{assetIds(entry).join('、')}}</p><pre v-if="entry.evidence">{{evidenceText(entry.evidence)}}</pre></details></article><p v-if="detail&&!detail.observations.length" class="seed-empty">{{tr('尚无可展示的历史观察；首次时间和轮次不作推断。','No historical observations are available. First-seen time and round are not inferred.')}}</p></div></div>
    <footer v-if="detail" class="seed-pagination history-pagination"><span>{{numberLabel(detail.observationsTotal)}} {{tr('条历史','observations')}} · {{detailPage}} / {{historyPages}}</span><button class="button ghost compact" :disabled="detailReading||detailPage<=1" data-seeds-action="previous-history" @click="changeHistoryPage(detailPage-1)"><ChevronLeft :size="14"/></button><button class="button ghost compact" :disabled="detailReading||detailPage>=historyPages" data-seeds-action="next-history" @click="changeHistoryPage(detailPage+1)"><ChevronRight :size="14"/></button></footer>
   </aside>
